#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TENTATIVI 7

int main(void)
{
    // Genera un numero pseudo-casuale tra 0 (incluso) e 100 (escluso)
    srand(time(0));
    int numero = rand() % 100;

    int tentativi = 0;
    int num_tentativi = 0;

    while (tentativi < MAX_TENTATIVI) {
        int utente;
        printf("Indovina il numero: ");
        scanf("%d", &utente);

        if (utente == numero) {
            printf("Hai indovinato il numero! \n");
            break;
        } else if (utente > numero) {
            printf("Il numero è troppo alto. Prova di nuovo! \n");
        } else {
            printf("Il numero è troppo basso. Prova di nuovo! \n");
        }

        tentativi++;
        num_tentativi++;
    }

    if (tentativi == MAX_TENTATIVI) {
        printf("Hai superato il numero di tentativi massimo! \n");
        printf("Il numero era: %d \n", numero);
    }

    return 0;
}
